-- Dedicated prototype only. Synthetic PostgreSQL subjects; not Auth token tests.
-- All accounts, schedules, employee changes and audit records roll back.
begin;
do $$
declare c uuid; owner_id uuid; hr_id uuid:=gen_random_uuid(); manager_id uuid:=gen_random_uuid(); staff_id uuid:=gen_random_uuid(); outside_id uuid:=gen_random_uuid();
 hr_person uuid; manager_person uuid; staff_person uuid; hr_email text; manager_email text; staff_email text; outside_email text;
 shift_id uuid; assigned uuid; record_id uuid; draft jsonb; change jsonb; saved jsonb; seq bigint;
begin
 if (select count(*) from public.companies)<>1 or to_regprocedure('public.assign_shift(jsonb)') is null then raise exception 'Expected initialized HRIS shift deployment.';end if;
 select id,companies.owner_id into strict c,owner_id from public.companies;
 hr_email:='qa-shift-hr-'||hr_id||'@example.invalid'; manager_email:='qa-shift-manager-'||manager_id||'@example.invalid'; staff_email:='qa-shift-staff-'||staff_id||'@example.invalid';outside_email:='qa-shift-outside-'||outside_id||'@example.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(hr_id,hr_email,now()),(manager_id,manager_email,now()),(staff_id,staff_email,now()),(outside_id,outside_email,now());
 perform set_config('request.headers','{"x-hris-leave-contract":"2"}',true);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 perform public.save_company_account(hr_id,hr_email,'hr_generalist',true,null,null);
 perform public.save_company_account(manager_id,manager_email,'manager',true,null,null);
 perform public.save_company_account(staff_id,staff_email,'employee',true,null,null);
 perform public.save_company_account(outside_id,outside_email,'manager',true,null,null);
 select employee_id into hr_person from public.company_members where user_id=hr_id;
 select employee_id into manager_person from public.company_members where user_id=manager_id;
 select employee_id into staff_person from public.company_members where user_id=staff_id;
 update public.employees set reports_to=manager_person,joined_on='2020-01-01' where id=staff_person;
 draft:='{"id":null,"expected_revision":null,"name":"Synthetic rollback night shift","days":[1,2,3,4,5,6,7],"start_minute":1320,"end_minute":360,"works_on_holidays":true,"active":true}';
 perform set_config('request.jwt.claim.sub',hr_id::text,true);shift_id:=public.save_shift_template(draft);
 change:=jsonb_build_object('employee_id',staff_person,'template_id',shift_id,'effective_on','2026-01-01','expected_sequence',0,'expected_template_revision',0,'expected_timezone',(select timezone from public.companies where id=c),'reason','Synthetic rollback assignment');
 assigned:=public.assign_shift(change);
 assert (select plan->>'name'='Synthetic rollback night shift' and sequence=1 and actor_id=hr_id from public.shift_assignments where id=assigned),'Assignment snapshot or server actor mismatch';
 begin perform public.assign_shift(change);raise exception 'Stale assignment accepted';exception when sqlstate 'PT409' then null;end;
 begin update public.shift_assignments set reason='Forged' where id=assigned;raise exception 'Immutable assignment write allowed';exception when insufficient_privilege then null;end;
 begin delete from public.shift_template_versions where template_id=shift_id;raise exception 'Version deletion allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);
 assert exists(select 1 from public.shift_assignments where id=assigned),'Manager lacks direct-report assignment';
 assert not exists(select 1 from public.shift_template_versions where template_id=shift_id),'Manager read HR template audit';
 begin perform public.assign_shift(change);raise exception 'Manager assignment write allowed';exception when insufficient_privilege then null;end;
 begin perform public.save_shift_template(draft);raise exception 'Manager template write allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outside_id::text,true);
 assert not exists(select 1 from public.shift_assignments where id=assigned),'Unrelated manager read employee schedule';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 assert exists(select 1 from public.shift_assignments where id=assigned),'Employee cannot read own future-portal schedule scope';
 begin perform public.assign_shift(change);raise exception 'Employee assignment write allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',hr_id::text,true);
 select to_jsonb(t) into saved from public.shift_templates t where id=shift_id;
 perform public.save_shift_template(saved||jsonb_build_object('expected_revision',0,'name','Synthetic renamed night','active',false));
 assert (select plan->>'name'='Synthetic rollback night shift' from public.shift_assignments where id=assigned),'Template edit rewrote assignment';
 begin perform public.save_shift_template(saved||jsonb_build_object('expected_revision',0));raise exception 'Stale template accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.assign_shift(change||jsonb_build_object('expected_sequence',1,'expected_template_revision',1));raise exception 'Inactive shift assigned';exception when check_violation then null;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.save_company_account(hr_id,hr_email,'hr_generalist',false,null,null);
 perform set_config('request.jwt.claim.sub',hr_id::text,true);
 assert not exists(select 1 from public.shift_assignments),'Disabled HR retained schedule scope';
 assert not exists(select 1 from public.shift_templates),'Disabled HR retained template scope';
 begin perform public.save_shift_template(draft);raise exception 'Disabled HR template write allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';
 begin perform * from public.shift_assignments;raise exception 'Anonymous assignment read allowed';exception when insufficient_privilege then null;end;
 begin perform public.assign_shift(change);raise exception 'Anonymous assignment write allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 assert not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef),'Public definer RPC exposed';
 assert (select count(*)=3 from pg_class t join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname in ('shift_templates','shift_assignments','shift_template_versions') and t.relrowsecurity),'Schedule RLS is missing';
end;
$$;
rollback;
